 public static void Build(){Directory.CreateDirectory(O+"/Bundle");var result=RebirthAssetBundlePackaging.BuildAssetBundles(O+"/Bundle",new[]{new AssetBundleBuild{assetBundleName="rebirth_camper80s.unity3d",assetNames=new[]{F+"/rebirthCamper80s.prefab"}}},BuildAssetBundleOptions.ChunkBasedCompression,BuildTarget.StandaloneWindows64);if(!result)throw new Exception("Build failed");var b=AssetBundle.LoadFromFile(O+"/Bundle/rebirth_camper80s.unity3d");var root=Object.Instantiate(b.LoadAsset<GameObject>("rebirthCamper80s"));if(root.GetComponentsInChildren<Collider>(true).Count(c=>c.name.StartsWith("REBIRTHInteraction_"))!=21)throw new Exception("Targets");RebirthCamperCampIntegration.SetMode(root,true);Physics.SyncTransforms();var log=new List<string>{Drop(0,1.25f,1.175f),Drop(0,.5f,2.945f),RebirthCamperDefectAudit.Walk(root,1.8f,.1f)};if(!log.Last().Contains("entry=True"))throw new Exception("Entry regression");File.WriteAllLines(O+"/bundle-verified.txt",log);}
